    /// `firstSixMinCVD` 13: the first `promisedDistinct` (6) inks stay apart for normal vision and every dichromacy.
    func testPromisedInksStayApartUnderEveryVision() {
        for mode in QuireMode.allCases {
            let closest = PaletteMath.closestPair(PaletteMath.accountInks(mode).prefix(6), kinds: CVDKind.allCases)
            XCTAssertGreaterThanOrEqual(closest.distance, 13 - 1e-9, "\(mode): \(closest.label)")
        }
    }

    /// `firstSixTargetStandard` 14: the same floor, raised for the standard-contrast modes.
    func testPromisedInksMeetTheStandardContrastTarget() {
        for mode in [QuireMode.light, .dark] {
            let closest = PaletteMath.closestPair(PaletteMath.accountInks(mode).prefix(6), kinds: CVDKind.allCases)
            XCTAssertGreaterThanOrEqual(closest.distance, 14 - 1e-9, "\(mode): \(closest.label)")
        }
    }

    /// `allTenMinNormal` 13: all ten inks stay apart for normal vision.
    func testAllInksStayApartForNormalVision() {
        for mode in QuireMode.allCases {
            let closest = PaletteMath.closestPair(PaletteMath.accountInks(mode)[...], kinds: [.normal])
            XCTAssertEqual(PaletteMath.accountInks(mode).count, 10)
            XCTAssertGreaterThanOrEqual(closest.distance, 13 - 1e-9, "\(mode): \(closest.label)")
        }
    }

    /// `minFromAccentNormal` 15: no ink sits within that distance of `accent`.
    func testInksKeepClearOfAccent() {
        for mode in QuireMode.allCases {
            let closest = PaletteMath.closestTo("accent", mode: mode, kinds: [.normal])
            XCTAssertGreaterThanOrEqual(closest.distance, 15 - 1e-9, "\(mode): \(closest.label)")
        }
    }

    /// `minFromDangerAnyVision` 10: no ink sits within that distance of `danger`.
    func testInksKeepClearOfDangerUnderEveryVision() {
        for mode in QuireMode.allCases {
